namespace sv_6fdeafef92ba437897315ad7b78ae869.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@rendermode InteractiveServer
@using sv_6fdeafef92ba437897315ad7b78ae869.Services
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-3">Product Catalog</h1>

<div class="d-flex flex-row gap-4">
    @* ── Left sidebar: filters (25%) ── *@
    <aside class="catalog-sidebar">
        <div class="card">
            <div class="card-header fw-semibold">Filters</div>
            <div class="card-body">
                @* Categories *@
                <h6>Category</h6>
                @if (categories is not null)
                {
                    @foreach (var cat in categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                   checked="@selectedCategories.Contains(cat)"
                                   @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                        </div>
                    }
                }
                else
                {
                    <p class="text-muted small">Loading…</p>
                }

                <hr />

                @* Price range *@
                <h6>Price Range</h6>
                <div class="d-flex gap-2 mb-2">
                    <input type="number" class="form-control form-control-sm" placeholder="Min"
                           @bind="minPrice" @bind:event="oninput" min="0" />
                    <input type="number" class="form-control form-control-sm" placeholder="Max"
                           @bind="maxPrice" @bind:event="oninput" min="0" />
                </div>

                <hr />

                @* In stock toggle *@
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="inStockToggle"
                           @bind="inStockOnly" />
                    <label class="form-check-label" for="inStockToggle">In Stock Only</label>
                </div>

                @* Action buttons *@
                <div class="d-grid gap-2">
                    <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
                    <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
                </div>
            </div>
        </div>
    </aside>

    @* ── Main content area (75%) ── *@
    <section class="catalog-main flex-grow-1">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading…</span>
                </div>
                <span class="ms-2">Loading products…</span>
            </div>
        }
        else if (result is not null && result.Items.Count == 0)
        {
            <div class="alert alert-info" role="alert">
                No products found matching your criteria. Try adjusting the filters.
            </div>
        }
        else if (result is not null)
        {
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="form-label me-2 mb-0" for="sortSelect">Sort by:</label>
                    <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
                            @bind="sortBy" @bind:after="LoadProducts">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted small">
                    Showing @ShowingStart–@ShowingEnd of @result.TotalCount products
                </span>
            </div>

            @* Product grid *@
            <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                @foreach (var product in result.Items)
                {
                    <div class="col">
                        <div class="card h-100 product-card" @onclick="() => OnProductSelected(product)"
                             role="button" tabindex="0">
                            <div class="product-image-placeholder d-flex align-items-center justify-content-center bg-light"
                                 title="@product.Name">
                                <span class="text-muted small text-center px-2">@product.Name</span>
                            </div>
                            <div class="card-body d-flex flex-column">
                                <h6 class="card-title mb-1">@product.Name</h6>
                                <p class="card-text fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                <p class="card-text mb-1">@RenderStars(product.Rating)</p>
                                @if (!product.InStock)
                                {
                                    <span class="badge bg-danger mb-2">Out of Stock</span>
                                }
                                <button class="btn btn-sm btn-success mt-auto"
                                        disabled="@(!product.InStock)"
                                        @onclick="() => { }" @onclick:stopPropagation="true">
                                    Add to Cart
                                </button>
                            </div>
                        </div>
                    </div>
                }
            </div>

            @* Pagination *@
            <nav class="mt-4" aria-label="Product pagination">
                <ul class="pagination justify-content-center">
                    <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                disabled="@(currentPage == 1)">Previous</button>
                    </li>
                    @for (int i = 1; i <= TotalPages; i++)
                    {
                        var pageNum = i;
                        <li class="page-item @(pageNum == currentPage ? "active" : "")">
                            <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                        </li>
                    }
                    <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                disabled="@(currentPage == TotalPages)">Next</button>
                    </li>
                </ul>
            </nav>
        }
    </section>
</div>

@code {
    [Parameter] public EventCallback<Product> OnProductClicked { get; set; }

    // Filter state
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Search state
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;
    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    // Computed helpers
    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int ShowingStart => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * result.PageSize + 1;

    private int ShowingEnd => result is null
        ? 0
        : Math.Min(result.Page * result.PageSize, result.TotalCount);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(BuildFilter(), sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = categoriesTask.Result;
            result = productsTask.Result;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter() => new(
        Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
        MinPrice: minPrice,
        MaxPrice: maxPrice,
        InStockOnly: inStockOnly
    );

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            result = await ProductService.SearchAsync(BuildFilter(), sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await LoadProducts();
    }

    private async Task OnProductSelected(Product product)
    {
        if (OnProductClicked.HasDelegate)
            await OnProductClicked.InvokeAsync(product);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        int empty = 5 - full;
        return new string('★', full) + new string('☆', empty);
    }
}

.catalog-sidebar {
    width: 25%;
    min-width: 220px;
    flex-shrink: 0;
}

.catalog-main {
    width: 75%;
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.15s ease-in-out, transform 0.15s ease-in-out;
}

.product-card:hover {
    box-shadow: 0 .5rem 1rem rgba(0, 0, 0, .15);
    transform: translateY(-2px);
}

.product-image-placeholder {
    height: 160px;
    border-bottom: 1px solid #dee2e6;
}

