    private int currentPage = 1;
    private const int PageSize = 9;
    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    // Computed helpers
    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int ShowingStart => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * result.PageSize + 1;

    private int ShowingEnd => result is null
        ? 0
        : Math.Min(result.Page * result.PageSize, result.TotalCount);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(BuildFilter(), sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = categoriesTask.Result;
