            errorMessage = null;
            result = await ProductService.SearchAsync(BuildFilter(), sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

